### 2. `StudentMapper.xml`（SQL 映射文件）

路径：`src/main/resources/mapper/StudentMapper.xml`

```xml
<?xml version="1.0" encoding="UTF-8" ?>
<!DOCTYPE mapper
        PUBLIC "-//mybatis.org//DTD Mapper 3.0//EN"
        "https://mybatis.org/dtd/mybatis-3-mapper.dtd">

<mapper namespace="com.atguigu.learn_test.mapper.StudentMapper">

    <!-- 根据 id 查询 -->
    <select id="getStudentById" resultType="com.atguigu.learn_test.dao.Student">
        select id, name, email, age
        from student
        where id = #{id}
    </select>

    <!-- 查询所有 -->
    <select id="getAllStudents" resultType="com.atguigu.learn_test.dao.Student">
        select id, name, email, age
        from student
    </select>

    <!-- 新增：useGeneratedKeys 用于回填自增主键到实体类的 id 属性 -->
    <insert id="addStudent" parameterType="com.atguigu.learn_test.dao.Student"
            useGeneratedKeys="true" keyProperty="id">
        insert into student (name, email, age)
        values (#{name}, #{email}, #{age})
    </insert>

    <!-- 更新 -->
    <update id="updateStudent" parameterType="com.atguigu.learn_test.dao.Student">
        update student
        set name = #{name},
            email = #{email},
            age = #{age}
        where id = #{id}
    </update>

    <!-- 删除 -->
    <delete id="deleteStudentById" parameterType="long">
        delete from student
        where id = #{id}
    </delete>

</mapper>
```

