    const API = 'http://localhost:8080';
    let currentKey = '';
    let selectedRole = 'STUDENT';   // 当前选中的角色（仅用于视觉）

    // 切换标签
    function switchTab(el) {
        document.querySelectorAll('.tabs div').forEach(d => d.classList.remove('active'));
        el.classList.add('active');
        selectedRole = el.dataset.role;
    }

    // 加载验证码
    async function loadCaptcha() {
        try {
            const res = await fetch(`${API}/captcha`);
            const data = await res.json();
            currentKey = data.key;
            document.getElementById('captchaImg').src = data.image;
        } catch (e) {
            console.error('加载验证码失败', e);
        }
    }

    document.getElementById('captchaImg').onclick = loadCaptcha;

    // 登录
    async function doLogin() {
        const username = document.getElementById('username').value;
        const password = document.getElementById('password').value;
        const captcha = document.getElementById('captcha').value;
        const msg = document.getElementById('message');

        if (!username || !password || !captcha) {
            msg.className = 'message error';
            msg.innerText = '请填写完整信息';
            return;
        }

        try {
            const res = await fetch(`${API}/auth/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password, captcha, key: currentKey })
            });
            const data = await res.json();

            if (data.success) {
                localStorage.setItem('token', data.token);
                localStorage.setItem('role', data.role);
                localStorage.setItem('username', data.username);

                msg.className = 'message success';
                msg.innerText = '登录成功，正在跳转...';

                setTimeout(() => {
                    if (data.role === 'ROLE_STUDENT') {
                        window.location.href = '/student.html';
                    } else if (data.role === 'ROLE_TEACHER') {
                        window.location.href = '/teacher.html';
                    } else if (data.role === 'ROLE_ADMIN') {
                        window.location.href = '/admin.html';
                    } else {
                        alert('未知角色：' + data.role);
                    }
                }, 500);

            } else {
                msg.className = 'message error';
                msg.innerText = data.message || '登录失败';
                loadCaptcha();
                document.getElementById('captcha').value = '';
            }
        } catch (e) {
            msg.className = 'message error';
            msg.innerText = '请求失败：' + e.message;
        }
    }

    document.getElementById('password').onkeydown = (e) => {
        if (e.key === 'Enter') doLogin();
    };

    loadCaptcha();
</script>

</body>
</html>
