## 📄 举例：抽取 `common.js`

在 `static/js/common.js` 里放公共函数：

```javascript
// 检查登录状态
function checkLogin() {
    const token = localStorage.getItem('token');
    if (!token) {
        window.location.href = '/login.html';
        return null;
    }
    return token;
}

// 退出登录
function logout() {
    localStorage.clear();
    window.location.href = '/login.html';
}

// 带 Token 的 fetch 封装
async function fetchWithToken(url, options = {}) {
    const token = localStorage.getItem('token');
    options.headers = {
        ...options.headers,
        'Authorization': 'Bearer ' + token
    };
    const res = await fetch(url, options);
    if (res.status === 401 || res.status === 403) {
        localStorage.clear();
        window.location.href = '/login.html';
        return null;
    }
    return res.json();
}
```

