<div class="login-box">
    <h2>教务系统登录</h2>

    <!-- 身份选择 -->
    <div class="role-select">
        <div class="role-card active" data-role="STUDENT" onclick="selectRole(this)">
            <span class="icon">🎓</span>
            <span class="label">学生端</span>
        </div>
        <div class="role-card" data-role="TEACHER" onclick="selectRole(this)">
            <span class="icon">👨‍🏫</span>
            <span class="label">教师端</span>
        </div>
        <div class="role-card" data-role="ADMIN" onclick="selectRole(this)">
            <span class="icon">🛠️</span>
            <span class="label">管理员端</span>
        </div>
    </div>

    <div class="form-item">
        <label>用户名</label>
        <input type="text" id="username" placeholder="请输入用户名">
    </div>

    <div class="form-item">
        <label>密码</label>
        <input type="password" id="password" placeholder="请输入密码">
    </div>

    <div class="form-item">
        <label>验证码</label>
        <div class="captcha-row">
            <input type="text" id="captcha" placeholder="请输入验证码">
            <img id="captchaImg" src="" alt="验证码" title="点击刷新">
        </div>
    </div>

    <button class="login-btn" id="loginBtn" onclick="doLogin()">学生登录</button>

    <div class="message" id="message"></div>
</div>

<script>
    const API = 'http://localhost:8080';
    let currentKey = '';
    let selectedRole = 'STUDENT';   // 当前选中的角色

    // 身份选择
    function selectRole(el) {
        document.querySelectorAll('.role-card').forEach(c => c.classList.remove('active'));
        el.classList.add('active');
        selectedRole = el.dataset.role;

        // 按钮文字跟着变
        const btn = document.getElementById('loginBtn');
        if (selectedRole === 'STUDENT') btn.innerText = '学生登录';
        else if (selectedRole === 'TEACHER') btn.innerText = '教师登录';
        else if (selectedRole === 'ADMIN') btn.innerText = '管理员登录';
    }

    // 加载验证码
    async function loadCaptcha() {
        try {
            const res = await fetch(`${API}/captcha`);
            const data = await res.json();
            currentKey = data.key;
            document.getElementById('captchaImg').src = data.image;
        } catch (e) {
            console.error('加载验证码失败', e);
        }
    }

    document.getElementById('captchaImg').onclick = loadCaptcha;

    // 登录
    async function doLogin() {
        const username = document.getElementById('username').value;
        const password = document.getElementById('password').value;
        const captcha = document.getElementById('captcha').value;
        const msg = document.getElementById('message');

        if (!username || !password || !captcha) {
            msg.className = 'message error';
            msg.innerText = '请填写完整信息';
            return;
        }

        try {
            const res = await fetch(`${API}/auth/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password, captcha, key: currentKey })
            });
            const data = await res.json();

            if (data.success) {
                localStorage.setItem('token', data.token);
                localStorage.setItem('role', data.role);
                localStorage.setItem('username', data.username);

                msg.className = 'message success';
                msg.innerText = '登录成功，正在跳转...';

                setTimeout(() => {
                    if (data.role === 'ROLE_STUDENT') {
                        window.location.href = '/student.html';
                    } else if (data.role === 'ROLE_TEACHER') {
                        window.location.href = '/teacher.html';
                    } else if (data.role === 'ROLE_ADMIN') {
                        window.location.href = '/admin.html';
                    } else {
                        alert('未知角色：' + data.role);
                    }
                }, 500);

            } else {
                msg.className = 'message error';
                msg.innerText = data.message || '登录失败';
                loadCaptcha();
                document.getElementById('captcha').value = '';
            }
        } catch (e) {
            msg.className = 'message error';
            msg.innerText = '请求失败：' + e.message;
        }
    }

    document.getElementById('password').onkeydown = (e) => {
        if (e.key === 'Enter') doLogin();
    };

    loadCaptcha();
</script>

</body>
</html>
